\title{Duality of Sublevel-Set Homotopy Types for RC Functions on Finite-Dimensional Banach Spaces}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We study the topology of sublevel sets of \emph{ratio-of-convex} (RC) functions $f = p/q$, where $p, q \ge 0$ are positively homogeneous convex functions of degree one on a finite-dimensional real Banach space. Such ratios are degree-zero homogeneous, so their sublevel sets are cones. To each RC function $f$ one associates a polarity dual $f\dual$, and the duality is realized in finite dimensions by an invertible continuous linear map $L$ --- the \emph{polarity map} --- satisfying the intertwining identity $f\dual \circ L = f$. We prove that this single identity forces a complete topological duality of the sublevel landscapes: (i) the polarity map carries each sublevel set of $f$ exactly onto that of $f\dual$, $\{f\dual \le c\} = L(\{f \le c\})$; (ii) it restricts to a homeomorphism $\{f \le c\} \cong \{f\dual \le c\}$; (iii) the two sublevel sets are homotopy equivalent; and (iv) the singular homology functor yields, in every degree $n$, an isomorphism $H_n(\{f \le c\}) \cong H_n(\{f\dual \le c\})$, with the identical statement for reduced homology. A central structural observation is that the topological conclusion uses \emph{only} the linearity and invertibility of $L$; convexity's role is confined to guaranteeing that such a linear polarity map exists. We record the cone-level specialization and a concrete non-vacuous instance on $\R^2$ with polarity realized by the coordinate swap.
\end{abstract}

\maketitle

\section{Introduction}

Sublevel sets are among the most ubiquitous geometric objects in mathematics and its applications. Given a function $f : X \to \R$ and a threshold $c \in \R$, the sublevel set is
\[
\{f \le c\} := \{\, x \in X \mid f(x) \le c \,\}.
\]
In optimization they are feasible regions; in physics they are basins of low energy; in topological data analysis they form the filtration whose evolving homology constitutes a \emph{persistence diagram}; and in Morse theory they are the elementary pieces from which the topology of a space is reconstructed, one critical value at a time. Knowing the homotopy type of $\{f \le c\}$ --- its connectivity and its holes in each dimension --- is knowing the coarse architecture of the problem $f$ encodes.

This paper concerns a precise topological \emph{duality} between the sublevel landscapes of two functions related by polarity.

\paragraph{Ratio-of-convex (RC) functions.} Let $p, q : X \to \R$ be non-negative, positively homogeneous of degree one, and convex. The associated RC function is the quotient
\[
f = \frac{p}{q}, \qquad \text{defined on } \{x : q(x) > 0\}.
\]
The class includes ratios of norms, support functions, and gauges of convex bodies. RC functions are scale-invariant: since $p, q$ are degree-one homogeneous, $f$ is degree-zero homogeneous, $f(tx) = f(x)$ for $t > 0$, hence constant along rays. This forces every sublevel set $\{f \le c\}$ to be a \emph{cone} (a union of rays through the origin).

\paragraph{Polarity duality.} The theory of convex bodies equips gauges and support functions with a duality operation --- polarity, governed by the bipolar theorem --- that, in finite dimensions, is realized at the level of the ambient space by an invertible \emph{linear} map. Transported to RC functions, this produces a dual function $f\dual$ on a space $Y$ and an invertible continuous linear map $L : X \to Y$, the \emph{polarity map}, satisfying the intertwining identity
\begin{equation}\label{eq:intertwine}
f\dual(L(x)) = f(x) \qquad \text{for all } x. \tag{$\ast$}
\end{equation}
We prove that under \eqref{eq:intertwine} the sublevel sets of $f$ and $f\dual$ are homeomorphic via $L$ and consequently have isomorphic (reduced) homology in all degrees. Our main structural finding is that the topological half is \emph{purely formal}: it depends only on $L$ being a linear homeomorphism intertwining $f$ and $f\dual$, not on convexity. Convexity is the (essential) provider of the map $L$; once $L$ is in hand, topology does the rest by functoriality.

\paragraph{Contributions.}
\begin{enumerate}
\item \textbf{The image identity} (Theorem~\ref{thm:image}): $\{f\dual \le c\} = L(\{f \le c\})$ for every $c$.
\item \textbf{The explicit duality homeomorphism} (Theorem~\ref{thm:homeo}): $L$ restricts to a homeomorphism $\{f \le c\} \cong \{f\dual \le c\}$, the same map for every $c$.
\item \textbf{Equal homotopy type} (Theorem~\ref{thm:homotopy}).
\item \textbf{Homology duality in all degrees} (Theorem~\ref{thm:homology}), with the same statement for reduced homology.
\item \textbf{Cone specialization} (Theorem~\ref{thm:cone}).
\item \textbf{A concrete non-vacuous instance} (Section~\ref{sec:example}).
\end{enumerate}

\section{Setting and definitions}

Throughout, $X$ and $Y$ are finite-dimensional real Banach spaces; in the formalization they are general real normed spaces, finite-dimensionality being the geometric context in which the polarity map is automatically linear.

\begin{definition}[Positive homogeneity]
A function $g : X \to \R$ is \emph{positively homogeneous of degree $k$} if $g(tx) = t^k g(x)$ for all $t > 0$ and all $x$. Degree-one is $k=1$; degree-zero, $g(tx) = g(x)$, expresses scale invariance.
\end{definition}

\begin{definition}[Convex gauge]
A \emph{non-negative homogeneous convex function} is $g : X \to \R$ with $g \ge 0$, positively homogeneous of degree one, and convex. Norms and gauges of convex bodies containing the origin are prototypical.
\end{definition}

\begin{definition}[RC function and its ratio]
Given non-negative degree-one homogeneous convex $p, q : X \to \R$, the \emph{ratio} is
\[
\ratio(p, q)(x) = \frac{p(x)}{q(x)}, \qquad x \in \{q > 0\}.
\]
We write $f = p/q$. It is degree-zero homogeneous: for $t > 0$,
\begin{equation}\label{eq:homog}
f(tx) = \frac{p(tx)}{q(tx)} = \frac{t\,p(x)}{t\,q(x)} = f(x),
\end{equation}
the fact recorded in the formalization as \texttt{ratio\_smul\_pos}.
\end{definition}

\begin{definition}[Sublevel set]
For $f : X \to \R$ and $c \in \R$, $\{f \le c\} = \{x : f(x) \le c\}$, a topological subspace of $X$. In Lean this is the subtype \texttt{\{x // f x $\le$ c\}}.
\end{definition}

\begin{definition}[Division-free sublevel cone]\label{def:cone}
The \emph{sublevel cone} of $f = p/q$ is
\[
\coneSub(p, q, c) = \{\, x : p(x) \le c\, q(x) \,\},
\]
recording $p \le c\,q$ directly. On $\{q > 0\}$ it coincides with $\{f \le c\}$, but it is defined everywhere and is a cone: if $x \in \coneSub(p,q,c)$ and $t > 0$ then $p(tx) = t\,p(x) \le t\,c\,q(x) = c\,q(tx)$, so $tx \in \coneSub(p,q,c)$. This closure property is \texttt{coneSub\_smul\_mem}.
\end{definition}

\begin{definition}[Polarity map and intertwining]
A \emph{polarity map} between RC functions $f$ on $X$ and $f\dual$ on $Y$ is an invertible continuous linear map with continuous inverse, $L : X \xrightarrow{\sim} Y$ (in Lean, $X \simeq_{L[\R]} Y$), satisfying the intertwining identity \eqref{eq:intertwine}: $f\dual(L(x)) = f(x)$ for all $x$. In the formalization this is \texttt{hdual : $\forall$ x, fdual (L x) = f x}. The map $L$ is a single fixed map, independent of $c$.
\end{definition}

\begin{remark}[Coefficients and functoriality]
Singular homology is developed as a functor $\mathrm{TopCat} \to C$ valued in an arbitrary homological category $C$ (preadditive, with the requisite coproducts and a homology calculus) and a chosen coefficient object $R \in C$. The classical case $C = R\text{-Mod}$ recovers ordinary singular homology with coefficients in a ring $R$. All homology statements hold at this generality; the reader may instantiate $C = \Z\text{-Mod}$, $R = \Z$.
\end{remark}

\section{Main results}

We fix RC functions $f : X \to \R$, $f\dual : Y \to \R$, an invertible continuous linear polarity map $L : X \to Y$, and assume \eqref{eq:intertwine}. Fix $c \in \R$.

\begin{theorem}[Polarity carries sublevel sets onto sublevel sets; \texttt{sublevel\_image}]\label{thm:image}
\[
\{\, y \in Y \mid f\dual(y) \le c \,\} = L\big(\{\, x \in X \mid f(x) \le c \,\}\big).
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\subseteq$) Let $f\dual(y) \le c$ and set $x := L^{-1}(y)$. Then $f(x) = f\dual(L(L^{-1}(y))) = f\dual(y) \le c$ by \eqref{eq:intertwine}, so $y = L(x) \in L(\{f \le c\})$; invertibility supplies the preimage.
($\supseteq$) If $y = L(x)$ with $f(x) \le c$, then $f\dual(y) = f\dual(L(x)) = f(x) \le c$. Both inclusions hold for every $c$ with the same $L$.
\end{proof}

\begin{theorem}[Duality homeomorphism; \texttt{sublevelHomeo}]\label{thm:homeo}
The linear polarity map $L$ restricts to a homeomorphism
\[
\Phi_c : \{\, x : f(x) \le c \,\} \xrightarrow{\;\cong\;} \{\, y : f\dual(y) \le c \,\}, \qquad \Phi_c(x) = L(x).
\]
\end{theorem}

\begin{proof}[Proof sketch]
$L$ is a homeomorphism $X \cong Y$. By \eqref{eq:intertwine} it maps the source sublevel condition into the target one, and by Theorem~\ref{thm:image} its inverse maps back; thus it restricts to a homeomorphism of subspaces (\texttt{ContinuousLinearEquiv.toHomeomorph} composed with \texttt{Homeomorph.subtype}, the subspace condition discharged by rewriting with \eqref{eq:intertwine}).
\end{proof}

\begin{lemma}[Action of the homeomorphism; \texttt{sublevelHomeo\_apply}]\label{lem:apply}
For $x \in \{f \le c\}$, the underlying point of $\Phi_c(x)$ in $Y$ is exactly $L(x)$. (In the formalization, definitional, by \texttt{rfl}.)
\end{lemma}

The crucial feature: $\Phi_c$ is induced by one fixed linear map $L$ for \emph{all} $c$, which permits promotion to filtrations and Morse theory (Section~\ref{sec:apps}).

\begin{theorem}[Same homotopy type; \texttt{sublevel\_homotopyEquiv}]\label{thm:homotopy}
$\{f \le c\}$ and $\{f\dual \le c\}$ are homotopy equivalent.
\end{theorem}

\begin{proof}[Proof sketch]
Every homeomorphism is a homotopy equivalence (its inverse is a homotopy inverse, the composites being equal to the identities). Apply to $\Phi_c$ of Theorem~\ref{thm:homeo}.
\end{proof}

\begin{theorem}[Duality homology isomorphism; \texttt{sublevelHomologyIso}, \texttt{sublevel\_homology\_iso}]\label{thm:homology}
For every degree $n \in \N$ there is an isomorphism
\[
H_n\big(\{\, x : f(x) \le c \,\}\big) \cong H_n\big(\{\, y : f\dual(y) \le c \,\}\big),
\]
where $H_n = ((\text{singularHomologyFunctor}\; C\; n).\mathrm{obj}\, R)$. The same holds for reduced homology.
\end{theorem}

\begin{proof}[Proof sketch]
Singular homology is a functor $\mathrm{TopCat} \to C$; functors send isomorphisms to isomorphisms. The homeomorphism $\Phi_c$ is an isomorphism in $\mathrm{TopCat}$ (\texttt{TopCat.isoOfHomeo}); applying the homology functor (\texttt{mapIso}) yields an isomorphism in each degree $n$. No homology group is computed; the isomorphism is automatic by functoriality. The reduced version is the same argument for the augmented complex.
\end{proof}

\begin{theorem}[Cone duality; \texttt{coneSubHomeo}]\label{thm:cone}
Let $f = p/q$ on $X$ and $f\dual = p'/q'$ on $Y$ be RC functions, and suppose $L$ carries each sublevel cone of $f$ to that of $f\dual$:
\[
x \in \coneSub(p, q, c) \iff L(x) \in \coneSub(p', q', c) \quad \text{for all } x.
\]
Then $L$ restricts to a homeomorphism $\coneSub(p, q, c) \cong \coneSub(p', q', c)$.
\end{theorem}

\begin{proof}[Proof sketch]
As in Theorem~\ref{thm:homeo}: $L$ is a homeomorphism $X \cong Y$, and the membership equivalence is exactly the condition for \texttt{Homeomorph.subtype} to restrict it to the two cone subspaces.
\end{proof}

\section{The role of convexity}

\begin{observation}[Convexity is offstage]
Every conclusion of the previous section --- the image identity, the homeomorphism, the homotopy equivalence, the homology isomorphism --- follows from the single hypothesis that $L$ is an invertible continuous linear map intertwining $f$ and $f\dual$. Convexity of $p, q$ is never used in these arguments.
\end{observation}

Convexity appears in the conjecture because it is responsible for the \emph{existence and linearity} of $L$: the polarity duality of convex bodies (and the bipolar theorem) guarantees, in finite dimensions, that the abstract duality of the gauges $p, q$ is realized by a linear isomorphism $L$. Thus convexity (analysis) produces a linear $L$ with $f\dual \circ L = f$, while linearity and invertibility (topology) turn it into a homeomorphism and hence a homology isomorphism. The natural generalization: the topological duality holds for any class of degree-zero homogeneous functions whose duality is realized linearly.

\section{A concrete non-vacuous instance}\label{sec:example}

On $X = Y = \R^2$, define
\[
p(x, y) = |x|, \quad q(x, y) = |x| + |y|, \quad f(x, y) = \frac{|x|}{|x| + |y|},
\]
and the dual data
\[
p\dual(x, y) = |y|, \quad q\dual(x, y) = |x| + |y|, \quad f\dual(x, y) = \frac{|y|}{|x| + |y|}.
\]
Each of $p, q, p\dual, q\dual$ is non-negative, convex, and degree-one homogeneous; $f, f\dual$ are degree-zero homogeneous off the origin. Take the coordinate swap $L(x, y) = (y, x)$, a non-identity continuous linear equivalence (\texttt{ContinuousLinearEquiv.prodComm}) with $L^{-1} = L$. Then
\[
f\dual(L(x, y)) = f\dual(y, x) = \frac{|x|}{|y| + |x|} = \frac{|x|}{|x| + |y|} = f(x, y),
\]
so \eqref{eq:intertwine} holds and all conclusions apply. As subsets of $\R^2$ the sets differ: $\{f \le c\}$ clusters around the $y$-axis, $\{f\dual \le c\}$ around the $x$-axis, exchanged by reflection across $y = x$. For $c = \tfrac12$, $\{f \le \tfrac12\} = \{|x| \le |y|\}$ and $\{f\dual \le \tfrac12\} = \{|y| \le |x|\}$, swapped exactly by $L$.

\section{Applications and connections}\label{sec:apps}

\paragraph{TDA and persistence.} Since $L$ is the same for every $c$, it commutes with sublevel inclusions $\{f \le c\} \hookrightarrow \{f \le c'\}$ and descends to an isomorphism of the entire sublevel filtrations of $f$ and $f\dual$; their persistence modules are isomorphic and their persistence diagrams identical.

\paragraph{Morse theory.} The topology of $\{f \le c\}$ changes only at critical values of $f$. Uniformity of $L$ in $c$ makes the critical values and transitions of $f$ correspond one-to-one with those of $f\dual$: the two RC functions are Morse-theoretic twins.

\paragraph{Convex geometry and optimization.} RC functions arise as ratios of gauges and support functions (fractional programs, Rayleigh quotients); the duality transfers feasible-region topology to whichever formulation is more tractable.

\paragraph{Computation.} The image identity reduces computing the dual landscape to applying a single linear map, with topological invariants guaranteed equal a priori.

\section{Discussion}

The results isolate a clean principle: a duality of degree-zero-homogeneous functions realized by an invertible linear intertwiner is automatically a topological duality of sublevel sets, in every degree and at every level. Two features stand out: \emph{uniformity in $c$} (a single map at all levels, enabling the filtration/Morse statements) and \emph{separation of hypotheses} (convexity provides the map; linearity provides the topology). A limitation by design is that the existence and linearity of $L$ are assumed, not derived; establishing necessity (Conjecture~C2) would show the linear polarity map is canonical.

\section{Future directions}

\begin{conjecture}[C1: cone deformation-retracts onto its spherical link]
Every RC sublevel cone $\coneSub(p, q, c)$, minus the origin, deformation-retracts onto its intersection with the unit sphere; hence its reduced homology equals that of the link. The radial map $x \mapsto x/\|x\|$ is the retraction, converting a computation in $\R^n$ into one on $S^{n-1}$, upgrading Theorem~\ref{thm:homotopy} to an explicit homology computation.
\end{conjecture}

\begin{conjecture}[C2: linearity is forced]
For non-negative degree-one convex gauges $p, q$ in finite dimensions, the sublevel duality is realizable by no map other than a linear isomorphism (up to the cone's automorphisms), since a homogeneous convex gauge is determined by its unit ball and polarity is induced by the linear bipolar duality.
\end{conjecture}

\begin{conjecture}[C3: Morse-theoretic invariance]
The isomorphism $H_*(\{f \le c\}) \cong H_*(\{f\dual \le c\})$ persists across all regular values $c$ and changes only at the shared critical values of $f$ and $f\dual$, yielding a level-by-level Morse equivalence, since the polarity homeomorphism is natural in $c$.
\end{conjecture}

\begin{conjecture}[C4: minimality of the bipolar identity]
The intertwining identity \eqref{eq:intertwine} is the minimal hypothesis: no further regularity or convexity is needed for the topological conclusion, convexity being confined to the prior existence of $L$.
\end{conjecture}

\section{Conclusion}

From the single intertwining identity $f\dual \circ L = f$ follow the image identity $\{f\dual \le c\} = L(\{f \le c\})$, an explicit homeomorphism realized by $L$ at every level, the resulting homotopy equivalence, and an isomorphism of singular (and reduced) homology in all degrees, together with the division-free cone specialization. The conclusions are purely formal in $L$, with convexity responsible only for the existence of the map, and they are non-vacuous, as the planar coordinate-swap instance certifies.

