function TransportSublevel(samples, f, L, c):
    primal <- []
    for x in samples:
        if f(x) <= c:            # membership in {f <= c}
            primal.append(x)
    dual <- []
    for x in primal:
        dual.append(L(x))        # image identity: L(x) in {f_dual <= c}
    return dual                  # equals {f_dual <= c} on L(samples)

function DualityBetti0Equal(f, f_dual, n, extent, c):
    cells_p <- SublevelGrid(f, n, extent, c)
    cells_d <- SublevelGrid(f_dual, n, extent, c)
    b_p <- Betti0(cells_p)        # union-find over 4-neighbours
    b_d <- Betti0(cells_d)
    return (b_p, b_d, b_p == b_d)

function Betti0(cells):
    init union-find over cells
    for cell in cells:
        for nbr in 4-neighbours(cell):
            if nbr in cells: union(cell, nbr)
    return number of distinct roots

